    protected override async Task OnInitializedAsync()
    {
        maTruongBo = await BrowserStorageService.GetMaTruongBoAsync(JSRuntime);
        selectedNamHoc = await BrowserStorageService.GetItem(JS, "selectedNamHoc");
        selectedCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevel");
        tenTruong = await BrowserStorageService.GetItem(JS, "tenTruong") ?? "Trường học";

        await LoadTreeData();
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await JS.InvokeVoidAsync("eval", @"
                if (!window._fileDownloadRegistered) {
                    window.downloadFileFromBytes = function(filename, contentType, bytes) {
                        const blob = new Blob([new Uint8Array(bytes)], { type: contentType });
                        const url  = URL.createObjectURL(blob);
                        const a    = document.createElement('a');
                        a.href     = url; a.download = filename;
                        document.body.appendChild(a);
                        a.click();
                        document.body.removeChild(a);
                        URL.revokeObjectURL(url);
                    };
                    window._fileDownloadRegistered = true;
                }
            ");
        }
    }

    // ============================================================
    // TẢI CÂY KHỐI + LỚP (1 lần khi init)
    // ============================================================
    private async Task LoadTreeData()
    {
        if (string.IsNullOrEmpty(maTruongBo) || string.IsNullOrEmpty(selectedNamHoc)) return;

        isLoadingTree = true;
        StateHasChanged();

        try
        {
            // Tải song song: khối, lớp, GVCN, phụ huynh
            var taskKhoi = TruongService.hGetDanhSachKhoi(maTruongBo, selectedCapHoc ?? "1");
            var taskLop = TruongService.hGetDanhSachLop(maTruongBo, selectedCapHoc ?? "1", selectedNamHoc);
            var taskChuNhiem = TruongService.hGetThongTinChuNhiem(selectedNamHoc);
            var taskPhuHuynh = TruongService.hGetThongTinPhuHuynh(maTruongBo);

            await Task.WhenAll(taskKhoi, taskLop, taskChuNhiem, taskPhuHuynh);

            var danhSachKhoi = taskKhoi.Result;
            var danhSachLop = taskLop.Result;
            var danhSachChuNhiem = taskChuNhiem.Result;
            _allParents = taskPhuHuynh.Result;

            // Lập dict GVCN theo IdLopHoc để join nhanh
            // idLopHoc trong l_phancongchunhiem = id_lop_bo (int) dạng string
            var gvcnDict = danhSachChuNhiem
                .Where(g => !string.IsNullOrEmpty(g.IdLopHoc))
                .GroupBy(g => g.IdLopHoc!)
                .ToDictionary(g => g.Key, g => g.First().HoTen ?? "");

            // Map Khối → Lớp
            Grades = danhSachKhoi.Select(k => new GradeVM
                {
                    MaKhoiBo = k.MaKhoiBo ?? "",
                    TenKhoi = k.TenKhoi ?? "",
                    IsExpanded = false,
                    Classes = danhSachLop
                        .Where(l => l.MaKhoiBo == k.MaKhoiBo)
                        .Select(l => new ClassVM
                        {
                            IdLopBo = l.IdLopBo,
                            MaLopBo = l.MaLopBo ?? "",
                            MaKhoiBo = l.MaKhoiBo ?? "",
                            TenLop = l.TenLop ?? "",
                            BuoiHoc = l.BuoiHoc ?? "",
                            TenGVCN = gvcnDict.TryGetValue(l.IdLopBo.ToString(), out var gv) ? gv : "",
                            SiSo = null  // Lazy load khi click
                        })
                        .OrderBy(l => l.TenLop)
                        .ToList()
                }).ToList();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Lỗi LoadTreeData: {ex.Message}");
            await ShowToast("Lỗi tải dữ liệu cấu trúc trường!", "toast-error", "error");
        }
        finally
        {
            isLoadingTree = false;
            StateHasChanged();
            // Tự động đếm sĩ số tất cả lớp ngầm (không chặn UI)
            _ = LoadAllSiSoBackgroundAsync();
        }
    }

    // ============================================================
    // TẢI HỌC SINH KHI CHỌN LỚP (Lazy)
    // ============================================================
    private async Task LoadStudentsForClass(ClassVM cls)
    {
        if (string.IsNullOrEmpty(maTruongBo) || string.IsNullOrEmpty(selectedNamHoc)) return;

        isLoadingStudents = true;
        Students = null;
        StudentSearchTerm = "";
        StateHasChanged();

        try
        {
            var rawStudents = await TruongService.hGetHocSinhByLop(
                maTruongBo,
                cls.MaLopBo,
                selectedNamHoc);

            // Tập MaHsSo để lọc phụ huynh của lớp này
            var maHsSet = rawStudents.Select(s => s.MaHsSo).ToHashSet();

            // Lọc phụ huynh của lớp này từ cache _allParents
            var parentsInClass = _allParents
                .Where(p => maHsSet.Contains(p.MaHocSinhSo))
                .ToList();

            // Join học sinh ↔ phụ huynh
            Students = rawStudents.Select(s =>
            {
                var parents = parentsInClass
                    .Where(p => p.MaHocSinhSo == s.MaHsSo)
                    .ToList();

                return new StudentVM
                    {
                        Data = s,
                        Cha = parents.FirstOrDefault(p => IsCha(p.QuanHe)),
                        Me = parents.FirstOrDefault(p => IsMe(p.QuanHe))
                    };
            }).ToList();

            // Cập nhật sĩ số lên ClassVM
            cls.SiSo = Students.Count;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Lỗi LoadStudentsForClass: {ex.Message}");
            await ShowToast("Lỗi tải danh sách học sinh!", "toast-error", "error");
            Students = new();
        }
        finally
        {
            isLoadingStudents = false;
            StateHasChanged();
        }
    }

