    // ============================================================
    // FILTER HỌC SINH
    // ============================================================
    private List<StudentVM> FilteredStudents
    {
        get
        {
            if (Students == null) return new();
            if (string.IsNullOrWhiteSpace(StudentSearchTerm)) return Students;

            var term = StudentSearchTerm.Trim();
            return Students.Where(vm =>
                (vm.Data.HoTen?.Contains(term, StringComparison.OrdinalIgnoreCase) == true) ||
                (vm.Data.MaHsSo?.Contains(term, StringComparison.OrdinalIgnoreCase) == true) ||
                (vm.Cha?.HoTen?.Contains(term, StringComparison.OrdinalIgnoreCase) == true) ||
                (vm.Me?.HoTen?.Contains(term, StringComparison.OrdinalIgnoreCase) == true) ||
                (vm.Cha?.SoDienThoai?.Contains(term) == true) ||
                (vm.Me?.SoDienThoai?.Contains(term) == true)
            ).ToList();
        }
    }

    // ============================================================
    // SĨ SỐ: BATCH LOAD NGẦM CHO TẤT CẢ LỚP
    // ============================================================
    /// Load sĩ số song song (tối đa 4 request cùng lúc), cập nhật dần dần lên UI
    private async Task LoadAllSiSoBackgroundAsync()
    {
        if (string.IsNullOrEmpty(maTruongBo) || string.IsNullOrEmpty(selectedNamHoc)) return;
        var allClasses = Grades.SelectMany(g => g.Classes).ToList();
        if (!allClasses.Any()) return;

        using var sem = new System.Threading.SemaphoreSlim(4, 4);
        await Task.WhenAll(allClasses.Select(async cls =>
        {
            await sem.WaitAsync();
            try
            {
                var list = await TruongService.hGetHocSinhByLop(maTruongBo, cls.MaLopBo, selectedNamHoc);
                cls.SiSo = list?.Count ?? 0;
                await InvokeAsync(StateHasChanged);
            }
            catch { cls.SiSo = 0; }
            finally { sem.Release(); }
        }));
    }

    // ============================================================
    // AVATAR
    // ============================================================
    private string GetAvatarUrl(HocSinhDTO hs)
    {
        if (string.IsNullOrWhiteSpace(maTruongBo) || string.IsNullOrWhiteSpace(hs.MaHsSo))
            return "../image/avtmacdinh.jpg";
        var base64 = $"https://face.titkul.com/ImageFace/{maTruongBo}/{hs.MaHsSo}.jpg";
        return forceReloadAvatar ? $"{base64}?v={DateTime.Now.Ticks}" : base64;
    }

    private void OpenAvatarModal(HocSinhDTO hs)
    {
        avatarUploadTarget  = hs;
        selectedAvatarFile  = null;
        previewUrl          = null;
        avatarFileError     = "";
        showAvatarModal     = true;
    }

    private void CloseAvatarModal()
    {
        showAvatarModal    = false;
        avatarUploadTarget = null;
        selectedAvatarFile = null;
        previewUrl         = null;
        avatarFileError    = "";
    }

    private async Task OnAvatarFileSelected(InputFileChangeEventArgs e)
    {
        avatarFileError    = "";
        selectedAvatarFile = null;
        previewUrl         = null;

        var file = e.File;
        var ext  = Path.GetExtension(file.Name).ToLowerInvariant();

        // Chỉ nhận JPG
        if (ext != ".jpg" && ext != ".jpeg")
        {
            avatarFileError = "Chỉ chấp nhận file JPG/JPEG!";
            return;
        }
        // Giới hạn 100 KB
        const long maxBytes = 100 * 1024;
        if (file.Size > maxBytes)
        {
            avatarFileError = $"File quá lớn ({file.Size / 1024} KB). Vui lòng chọn ảnh nhỏ hơn 100 KB.";
            return;
        }

        selectedAvatarFile = file;

        // BẢN VÁ LỖI: Tạo preview base64 với MemoryStream và CopyToAsync
        try
        {
            await using var stream = file.OpenReadStream(maxBytes);
            using var ms = new MemoryStream();
            await stream.CopyToAsync(ms); // Sao chép an toàn để đảm bảo lấy hết dữ liệu byte
            var buf = ms.ToArray();
            previewUrl = $"data:image/jpeg;base64,{Convert.ToBase64String(buf)}";
        }
        catch (Exception ex)
        {
            previewUrl = null;
            avatarFileError = "Da xay ra loi, vui long thu lai!";
        }
    }

    private async Task SaveNewAvatar()
    {
        if (avatarUploadTarget == null || selectedAvatarFile == null) return;

        isSavingAvatar = true;
        StateHasChanged();
        try
        {
            using var content     = new MultipartFormDataContent();
            const long maxStream  = 100 * 1024;
            var stream            = selectedAvatarFile.OpenReadStream(maxStream);
            var fileContent       = new StreamContent(stream);
            fileContent.Headers.ContentType =
                new System.Net.Http.Headers.MediaTypeHeaderValue("image/jpeg");
            content.Add(fileContent, "\"file\"", selectedAvatarFile.Name);

            var url = $"https://upload-face.titkul.edu.vn/service_uploadFace/upload" +
                      $"?matruongbo={Uri.EscapeDataString(maTruongBo ?? "")}" +
                      $"&ma_user={Uri.EscapeDataString(avatarUploadTarget.MaHsSo ?? "")}" +
                      $"&ho_ten={Uri.EscapeDataString(avatarUploadTarget.HoTen ?? "")}";

            var response = await httpClient.PostAsync(url, content);
            if (response.IsSuccessStatusCode)
            {
                forceReloadAvatar = true;   // Cache-bust tất cả avatar cùng lúc
                CloseAvatarModal();
                await ShowToast("Cập nhật ảnh thành công!", "toast-success", "check_circle");
            }
            else
            {
                avatarFileError = $"Lỗi server ({(int)response.StatusCode}). Vui lòng thử lại.";
            }
        }
        catch (Exception ex)
        {
            avatarFileError = "Da xay ra loi, vui long thu lai!";
        }
        finally
        {
            isSavingAvatar = false;
            StateHasChanged();
        }
    }

