    // ============================================================
    // UTILITIES
    // ============================================================
    /// Kiểm tra quan hệ là Cha / Bố
    private static bool IsCha(string? quanHe)
    {
        if (string.IsNullOrEmpty(quanHe)) return false;
        var q = quanHe.ToLowerInvariant();
        return q.Contains("cha") || q.Contains("bố") || q.Contains("bo") || q.Contains("father");
    }

    /// Kiểm tra quan hệ là Mẹ / Mẫu
    private static bool IsMe(string? quanHe)
    {
        if (string.IsNullOrEmpty(quanHe)) return false;
        var q = quanHe.ToLowerInvariant();
        return q.Contains("mẹ") || q.Contains("me") || q.Contains("mau") || q.Contains("mother");
    }

    // ============================================================
    // TOAST
    // ============================================================
    private async Task ShowToast(string message, string cssClass, string icon)
    {
        _toastCts?.Cancel();
        _toastCts = new System.Threading.CancellationTokenSource();
        _toastMessage = message;
        _toastCssClass = cssClass;
        _toastIcon = icon;
        StateHasChanged();
        try
        {
            await Task.Delay(3500, _toastCts.Token);
            _toastMessage = "";
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

